const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let lines = [];
rl.on('line', line => {
    lines.push(line.trim());
    if (lines.length === 2) {
        rl.close();
    }
});
​
rl.on('close', () => {
    let [n, x, y] = lines[0].split(' ').map(Number);
    let ans = lines[1].split(' ').map(Number);
    let res = 0;
    // 二进制枚举 二进制对应为1代表选择
    for (let mask = 1; mask < (1 << n); mask++) {
        let pos = [];
        for (let i = 0; i < n; i++) {
            if ((mask >> i) & 1) pos.push(i);
        }
        // 选择数量不等于x
        if (pos.length !== x) continue;
        let prod = 1;
        for (let i of pos) prod *= ans[i];
        // 判断相乘结果
        if (prod >= y) res++;
    }
​
    console.log(res);
});
