package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line1, _ := reader.ReadString('\n')
    parts := strings.Fields(line1)
    n, _ := strconv.Atoi(parts[0])
    x, _ := strconv.Atoi(parts[1])
    y, _ := strconv.Atoi(parts[2])
​
    line2, _ := reader.ReadString('\n')
    numsStr := strings.Fields(line2)
    ans := make([]int64, n)
    for i := 0; i < n; i++ {
        val, _ := strconv.ParseInt(numsStr[i], 10, 64)
        ans[i] = val
    }
​
    res := 0
    // 二进制枚举 二进制对应为1代表选择
    for mask := 1; mask < (1 << n); mask++ {
        pos := []int{}
        for i := 0; i < n; i++ {
            if mask&(1<<i) != 0 {
                pos = append(pos, i)
            }
        }
        // 选择数量不等于x
        if len(pos) != x {
            continue
        }
        prod := int64(1)
        for _, i := range pos {
            prod *= ans[i]
        }
        // 判断相乘结果
        if prod >= int64(y) {
            res++
        }
    }
​
    fmt.Println(res)
}
